import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 8 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"8","title":"Page 8 | Home","prev":"/page/7/","next":"/page/9/","posts":[{"title":"Mac M1系统配置C++环境","url":"/posts/2022-04-13-m1-cpp/","date":"2022-04-13 20:03","tags":["C++"],"html":"<p>最近在学习计算机图形学，需要配置C++环境和opencv来编译作业代码，于是我就开始折腾下M1如何编译C++代码了。</p>\\n<h2 id=\\"安装依赖\\" tabindex=\\"-1\\">安装依赖 <a class=\\"header-anchor\\" href=\\"#安装依赖\\" aria-label=\\"Permalink to &quot;安装依赖&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先你需要安装Mac下的包管理器 <a href=\\"https://brew.sh/\\" target=\\"_blank\\" rel=\\"noreferrer\\">homebrew</a>，官网有详细的安装教程，我就不赘述了。</p>\\n<p>接下来安装C++相关的依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> gcc</span><span style=\\"color:#032F62\\"> cmake</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后是图形学相关的依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> eigen</span><span style=\\"color:#032F62\\"> opencv</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"配置头文件路径\\" tabindex=\\"-1\\">配置头文件路径 <a class=\\"header-anchor\\" href=\\"#配置头文件路径\\" aria-label=\\"Permalink to &quot;配置头文件路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<blockquote>\\n<p>This script installs Homebrew to its preferred prefix (/usr/local for macOS Intel, /opt/homebrew for Apple Silicon and /home/linuxbrew/.linuxbrew for Linux) so that you don’t need sudo when you brew install.</p>\\n</blockquote>\\n<p>homebrew 官网有描述M1的安装路径更改到 <code>/opt/homebrew</code> 了。所以我们需要指定头文件路径，这里我们指定到 <code>/opt/homebrew/include</code>。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> CPATH</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">/opt/homebrew/include</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> LIBRARY_PATH</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">/opt/homebrew/lib</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>把上述代码添加到 <code>.bashrc</code> 文件，如果你使用的是 zsh 请添加到 <code>.zshrc</code> 文件。</p>\\n<h2 id=\\"检测头文件路径\\" tabindex=\\"-1\\">检测头文件路径 <a class=\\"header-anchor\\" href=\\"#检测头文件路径\\" aria-label=\\"Permalink to &quot;检测头文件路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">gcc</span><span style=\\"color:#005CC5\\"> -x</span><span style=\\"color:#032F62\\"> c++</span><span style=\\"color:#005CC5\\"> -v</span><span style=\\"color:#005CC5\\"> -E</span><span style=\\"color:#032F62\\"> /dev/null</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>如果输出结果有 <code>/opt/homebrew/include</code> 就说明配置成功了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>配置环境看似简单，但找到解决方案需要花不少时间，这里主要问题是M1下安装路径不同，所以我们需要指定头文件路径。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://apple.stackexchange.com/questions/414622/installing-a-c-c-library-with-homebrew-on-m1-macs\\" target=\\"_blank\\" rel=\\"noreferrer\\">Installing a C/C++ library with homebrew on M1 Macs</a></p>\\n<p><a href=\\"https://zhuanlan.zhihu.com/p/371245964\\" target=\\"_blank\\" rel=\\"noreferrer\\">在 Mac OS 下配置 GAMES101 开发环境</a></p>\\n<p><a href=\\"https://stackoverflow.com/questions/19852199/view-default-include-path-of-c-headers-in-mac-os-x-by-gcc-v\\" target=\\"_blank\\" rel=\\"noreferrer\\">View default include path of C headers in Mac OS X by gcc -v?</a></p>\\n"},{"title":"禁用页面滚动","url":"/posts/2022-03-13-scroll-lock/","date":"2022-03-13 15:11","tags":["web"],"html":"<p>在设计组件的时候，例如 Modal 弹窗组件，在显示组件的时候我们不希望页面可以滚动。这时候就需要临时禁用页面的滚动功能。接下来就讲解下禁用页面滚动的方法。</p>\\n<h2 id=\\"禁用滚动\\" tabindex=\\"-1\\">禁用滚动 <a class=\\"header-anchor\\" href=\\"#禁用滚动\\" aria-label=\\"Permalink to &quot;禁用滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>禁用滚动的方法很简单，只需要在页面的 body 元素上设置 overflow 属性为 hidden，就可以禁用页面的滚动了。但是我们需要考虑到，如果我们的页面有滚动条，滚动条的消失会影响页面的显示效果。\\n所以完美的禁用滚动方式需要考虑到当前页面滚动条的宽度。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    window.innerWidth </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> document.documentElement.clientWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> scrollbarWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> lockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scrollbarWidth) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">\`\${</span><span style=\\"color:#24292E\\">scrollbarWidth</span><span style=\\"color:#032F62\\">}px\`</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br></div></div><p>为了保证不影响页面的显示效果，我们需要计算出当前页面滚动条的宽度，然后设置 body 的 padding-right 属性，这样就可以保证页面的显示效果。</p>\\n<h2 id=\\"恢复滚动\\" tabindex=\\"-1\\">恢复滚动 <a class=\\"header-anchor\\" href=\\"#恢复滚动\\" aria-label=\\"Permalink to &quot;恢复滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> unlockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>恢复滚动只需要把添加到 CSS 属性删除即可。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果一直使用 Mac 的触摸板来编程的话，有时候很难意识到滚动条的存在，但是对于大多数的 Windows 用户来说，滚动条会一直存在的。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/mantinedev/mantine/blob/master/src/mantine-hooks/src/use-scroll-lock/use-scroll-lock.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">use-scroll-lock.ts</a></p>\\n"},{"title":"Github 存储大文件","url":"/posts/2022-02-10-github-lfs/","date":"2022-02-10 23:16","tags":["github"],"html":"<p>最近在做项目的时候，需要上传一个超过 200MB 的数据库文件到 Github 上保存，结果 Github 提示文件过大。这才知道 Github 对单文件有 100 MB 的容量限制。</p>\\n<h2 id=\\"问题介绍\\" tabindex=\\"-1\\">问题介绍 <a class=\\"header-anchor\\" href=\\"#问题介绍\\" aria-label=\\"Permalink to &quot;问题介绍&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>正常情况下，我们执行 add, commit 操作的时候都没啥问题。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>但是执行 push 操作的时候会返回错误。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Enumerating</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 21,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Counting</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (21/21), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Delta</span><span style=\\"color:#032F62\\"> compression</span><span style=\\"color:#032F62\\"> using</span><span style=\\"color:#032F62\\"> up</span><span style=\\"color:#032F62\\"> to</span><span style=\\"color:#005CC5\\"> 10</span><span style=\\"color:#032F62\\"> threads</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Compressing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Writing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), 153.95 MiB </span><span style=\\"color:#D73A49\\">|</span><span style=\\"color:#6F42C1\\"> 13.82</span><span style=\\"color:#032F62\\"> MiB/s,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Total</span><span style=\\"color:#005CC5\\"> 17</span><span style=\\"color:#24292E\\"> (delta </span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">), reused 0 (</span><span style=\\"color:#6F42C1\\">delta</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">), pack-reused 0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> Resolving</span><span style=\\"color:#032F62\\"> deltas:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (4/4), completed with 3 </span><span style=\\"color:#D73A49\\">local</span><span style=\\"color:#24292E\\"> objects.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> Trace:</span><span style=\\"color:#6A737D\\"> ###</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> See</span><span style=\\"color:#032F62\\"> http://git.io/iEPt8g</span><span style=\\"color:#032F62\\"> for</span><span style=\\"color:#032F62\\"> more</span><span style=\\"color:#032F62\\"> information.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> File</span><span style=\\"color:#032F62\\"> xxx.db</span><span style=\\"color:#032F62\\"> is</span><span style=\\"color:#005CC5\\"> 259.50</span><span style=\\"color:#032F62\\"> MB</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6F42C1\\">this</span><span style=\\"color:#032F62\\"> exceeds</span><span style=\\"color:#032F62\\"> GitHub's file size limit of 100.00 MB</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">remote: error: GH001: Large files detected. You may want to try Git Large File Storage - https://git-lfs.github.com.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">To https://github.com/acgotaku/switch.git</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\"> ! [remote rejected] master -> master (pre-receive hook declined)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">error: failed to push some refs to 'https://github.com/{user}/{repo}.git'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br></div></div><p>这里提示我们可以使用 Git Large File Storage 来解决。</p>\\n<h2 id=\\"安装-lfs\\" tabindex=\\"-1\\">安装 LFS <a class=\\"header-anchor\\" href=\\"#安装-lfs\\" aria-label=\\"Permalink to &quot;安装 LFS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>根据官网的教程进行安装：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> git-lfs</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后 cd 到对应的 repo：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {repo}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> install</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Updated</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> hooks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Git</span><span style=\\"color:#032F62\\"> LFS</span><span style=\\"color:#032F62\\"> initialized.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"重新提交\\" tabindex=\\"-1\\">重新提交 <a class=\\"header-anchor\\" href=\\"#重新提交\\" aria-label=\\"Permalink to &quot;重新提交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这时候我们需要保留文件的同时，取消 commit：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {REPO}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> reset</span><span style=\\"color:#005CC5\\"> --soft</span><span style=\\"color:#032F62\\"> HEAD^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>然后单独提交大文件：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> track</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Tracking</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .gitattributes</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>执行第一行命令之后会生成一个 <code>.gitattributes</code> 文件，记得这个也需要一并提交。</p>\\n<p>接下来执行普通的 add commit, push 三个步骤就可以了。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Github 针对大文件存储有一个月 1GB 流量的限制，所以如果到达限制了需要付费才能继续使用。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://qiita.com/kanaya/items/ad52f25da32cb5aa19e6\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub に 100MB 超のファイルを置く</a></p>\\n"}]},"relativePath":"page/8/index.md","filePath":"page/[page].md"}`),e={name:"page/8/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const y=s(e,[["render",l]]);export{b as __pageData,y as default};
